await tools.write({
  file_path: "/Users/oyamahappa/Documents/Agent/DSH/.work/parse_section.py",
  content: `import sys

path = sys.argv[1]
out = sys.argv[2]
buf = bytearray()
for line in open(path, "r", errors="replace"):
    parts = line.split("\\t")
    if len(parts) < 2:
        continue
    try:
        int(parts[0], 16)
    except ValueError:
        continue
    for chunk in parts[1:]:
        chunk = chunk.strip()
        if not chunk:
            continue
        try:
            buf += bytes.fromhex("".join(chunk.split()))
        except ValueError:
            continue
names = [n.decode("utf-8", "replace") for n in bytes(buf).split(b"\\x00") if n]
with open(out, "w") as f:
    f.write("\\n".join(names))
print(len(names))
`
});
