  file_path: "/Users/oyamahappa/Documents/Agent/DSH/.work/findstr.py",
  content: `import struct, sys

path = sys.argv[1]
data = open(path, "rb").read()

# sections: (name, addr, size, off)
secs = []
off = 32
ncmds = struct.unpack_from("<I", data, 16)[0]
for _ in range(ncmds):
    cmd, cmdsize = struct.unpack_from("<II", data, off)
    if cmd == 0x19:
        nsects = struct.unpack_from("<I", data, off+64)[0]
        soff = off + 72
        for _ in range(nsects):
            name = data[soff:soff+16].rstrip(b"\\x00").decode("latin1")
            addr, size, offset = struct.unpack_from("<QQI", data, soff+32)
            secs.append((name, addr, size, offset))
            soff += 80
    off += cmdsize

targets = [t.encode() for t in sys.argv[2:]]
for t in targets:
    print("== %s" % t.decode())
    start = 0
    while True:
        i = data.find(t, start)
        if i < 0:
            break
        va = None
        for name, addr, size, offset in secs:
            if offset and offset <= i < offset + size:
                va = addr + (i - offset)
                sec = name
                break
        print("  off=0x%08x va=%s sec=%s" % (i, ("0x%08x" % va) if va else "?", sec if va else "-"))
        start = i + 1
`
