await tools.write({
  file_path: "/Users/oyamahappa/Documents/Agent/DSH/.work/xref.py",
  content: `import struct, sys

path = sys.argv[1]
lo = int(sys.argv[2], 16)
hi = int(sys.argv[3], 16)
data = open(path, "rb").read()

start, end = 0x4000, 0x658214
hits = []
pc = start
while pc + 8 <= end:
    w = struct.unpack_from("<I", data, pc)[0]
    if (w & 0x9F000000) == 0x90000000:
        rd = w & 31
        immlo = (w >> 29) & 3
        immhi = (w >> 5) & 0x7FFFF
        imm = (immhi << 2) | immlo
        if imm & (1 << 20):
            imm -= (1 << 21)
        page = ((pc & ~0xFFF) + (imm << 12)) & 0xFFFFFFFFFFFFFFFF
        # scan next 4 instructions for add/ldr using rd
        for k in range(1, 5):
            p2 = pc + 4 * k
            if p2 + 4 > end:
                break
            w2 = struct.unpack_from("<I", data, p2)[0]
            tgt = None
            # add (immediate), 64-bit: 0x91000000
            if (w2 & 0xFF800000) == 0x91000000 or (w2 & 0xFF800000) == 0x11000000:
                rn = (w2 >> 5) & 31
                if rn == rd:
                    imm12 = (w2 >> 10) & 0xFFF
                    if (w2 >> 22) & 1:
                        imm12 <<= 12
                    tgt = page + imm12
            # ldr (literal) 64-bit: 0x58000000
            if (w2 & 0xFF000000) == 0x58000000:
                rn = (w2 >> 5) & 31
                if rn == rd:
                    imm19 = (w2 >> 5) & 0x7FFFF
                    if w2 & 0x80000000:
                        pass
                    tgt = None
            if tgt is not None and lo <= tgt <= hi:
                hits.append((pc, p2, tgt, w, w2))
    pc += 4

for h in hits:
    print("adrp@0x%08x add@0x%08x -> 0x%08x" % (h[0], h[1], h[2]))
print("total", len(hits))
`
});
const r = await tools.bash({
