    m = re.search(r"0x([0-9A-F]{8})\\s+(rebase|auth-rebase)\\s+0x([0-9A-F]{8})", line)
    if m:
        fixups.append((int(m.group(1), 16), int(m.group(3), 16)))

def xrefs(lo, hi, window=6):
    hits = []
    pc = 0x4000
    while pc + 4 * window <= 0x658214:
        w = struct.unpack_from("<I", data, pc)[0]
        if (w & 0x9F000000) == 0x90000000:
            rd = w & 31
            immlo = (w >> 29) & 3
            immhi = (w >> 5) & 0x7FFFF
            imm = (immhi << 2) | immlo
            if imm & (1 << 20):
                imm -= (1 << 21)
            page = ((pc & ~0xFFF) + (imm << 12)) & 0xFFFFFFFFFFFFFFFF
            for k in range(1, window):
                p2 = pc + 4 * k
                w2 = struct.unpack_from("<I", data, p2)[0]
                if (w2 & 0xFF800000) == 0x91000000 or (w2 & 0xFF800000) == 0x11000000:
                    rn = (w2 >> 5) & 31
                    if rn == rd:
                        imm12 = (w2 >> 10) & 0xFFF
                        if (w2 >> 22) & 1:
                            imm12 <<= 12
                        tgt = page + imm12
                        if lo <= tgt <= hi:
                            hits.append((pc, tgt))
        pc += 4
    return hits

for s in sys.argv[1:]:
    va = None
    for line in open(".work/str_all.txt", errors="replace"):
        pass
