    print("== %s  va=0x%08x" % (s, va))
    ptrs = [p for p, t in fixups if t == va]
    for p in ptrs:
        structaddr = p - 0x10
        print("   cfstring@0x%08x" % structaddr)
        for cs, tgt in xrefs(structaddr, structaddr):
            print("      code@0x%08x" % cs)
