    "struct CGVector", "struct UIOffset",
}


def zero_value(ret):
    if ret == "void":
        return None
    if ret in STRUCT_RETURNS or ret.startswith("struct "):
        return "(%s){0}" % ret
    if ret == "BOOL":
        return "NO"
    if ret in ("id", "Class", "SEL", "char *", "void *", "id /* block */"):
        return "NULL"
    if ret[0].isupper():
        return "nil"
